/**
 * Map an executeScript task's `output_schema` (the platform's tagged
 * `{ object: { properties: [{ bool: { name } }, ...] } }` shape) to the
 * workflow field type each declared property resolves to.
 *
 * Used by `to-tf.ts` (forward: building the `elementum_workflow_publish`
 * outputs' `fieldType` envelope) and `build.ts` (authoring-time: stamping
 * `OutputPropertyRef.valueType` on the catalog ref) — kept dependency-free
 * like `output-key-wire-name.ts` so importing it from either side can never
 * introduce a cycle.
 */
function isObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}
/** Map executeScript output_schema properties to refs keys (`result.<name>`). */
export function outputFieldTypesFromScriptSchema(schema) {
    if (!isObject(schema))
        return undefined;
    const objectNode = isObject(schema.object) ? schema.object : schema;
    const properties = objectNode.properties;
    if (!Array.isArray(properties))
        return undefined;
    const out = new Map();
    for (const property of properties) {
        if (!isObject(property))
            continue;
        for (const [kind, body] of Object.entries(property)) {
            if (!isObject(body) || typeof body.name !== "string")
                continue;
            const fieldType = kind === "bool" ? "BOOLEAN"
                // Platform publish/ref envelopes use NUMBER for whole numbers, not INTEGER
                // (Sanofi demoClassifyHacat: authored "integer" → state fieldType NUMBER).
                : kind === "integer" ? "NUMBER"
                    : kind === "number" ? "DECIMAL"
                        // "string" is a real, confirmed-text kind; anything else (e.g. "object")
                        // is an unmodeled schema kind falling back to the platform's own TEXT
                        // default — real for the wire, but callers that need to know whether
                        // this was an ACTUAL text kind (not a guess) should check `kind` too.
                        : "TEXT";
            out.set(`result.${body.name}`, { fieldType, multiple: false, kind });
            out.set(body.name, { fieldType, multiple: false, kind });
        }
    }
    return out.size > 0 ? out : undefined;
}
